import{_ as i,H as t,f as l,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"直播回放 | MCP&A2A协议如何解决智能体开发痛点","description":"","frontmatter":{},"headers":[{"level":2,"title":"你将获得","slug":"你将获得","link":"#你将获得","children":[]},{"level":2,"title":"要点提炼","slug":"要点提炼","link":"#要点提炼","children":[]}],"relativePath":"MCP&A2A前沿实战/直播回放｜MCP&A2A协议如何解决智能体开发痛点.md","filePath":"MCP&A2A前沿实战/直播回放｜MCP&A2A协议如何解决智能体开发痛点.md","lastUpdated":1795531178000}'),p={name:"MCP&A2A前沿实战/直播回放｜MCP&A2A协议如何解决智能体开发痛点.md"};function n(s,e,r,A,o,E){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="直播回放-mcp-a2a协议如何解决智能体开发痛点" tabindex="-1">直播回放 | MCP&amp;A2A协议如何解决智能体开发痛点 <a class="header-anchor" href="#直播回放-mcp-a2a协议如何解决智能体开发痛点" aria-label="Permalink to &quot;直播回放 | MCP&amp;A2A协议如何解决智能体开发痛点&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE/2.jpeg" alt=""></a></p><h2 id="你将获得" tabindex="-1">你将获得 <a class="header-anchor" href="#你将获得" aria-label="Permalink to &quot;你将获得&quot;">​</a></h2><ul><li><p>为什么 MCP&amp;A2A 协议诞生在此时此刻？</p></li><li><p>MCP 和 A2A 协议异同详解</p></li><li><p>MCP 和 A2A 解决了开发过程中的哪些痛点</p></li><li><p>手把手带你基于 A2A 快速开发智能体</p></li></ul><h2 id="要点提炼" tabindex="-1">要点提炼 <a class="header-anchor" href="#要点提炼" aria-label="Permalink to &quot;要点提炼&quot;">​</a></h2><p>大模型时代的技术背景与趋势</p><ul><li><p>当前正处于计算 2.0 时代，其核心是从精确计算转向概率性推理。</p></li><li><p>AI 正快速发展，智能体已能完成真实认知工作，预计未来将具备发现新知识的能力。</p></li><li><p>从农业时代的经验型智能，到工业时代的技能型智能，再到科技时代的知识型智能，如今进入协作型智能阶段。</p></li></ul><p>MCP 协议的作用与价值</p><ul><li><p>MCP 协议旨在连接大模型与外部工具，解决模型与现实世界的割裂问题。</p></li><li><p>它提供标准化接口，简化大模型对工具的调用过程，类似 USB 标准。</p></li><li><p>实战中，通过配置 server 和 client，MCP 可自动发现并调用工具，无需手动配置参数。</p></li></ul><p>A to A 协议的意义</p><ul><li><p>A to A 协议关注智能体之间的交互，为未来的多智能体协作奠定基础。</p></li><li><p>在实际应用中，不同智能体各司其职，通过协议实现高效沟通。</p></li><li><p>示例展示了一个本地智能体如何通过 A to A 协议调用其他智能体完成复杂任务。</p></li></ul><p>计算 1.0 与 2.0 的融合</p><ul><li><p>计算 1.0 代表结构化、精确的计算，而计算 2.0 则基于概率性和模糊推理。</p></li><li><p>大模型擅长处理自然语言任务，但数学计算等仍需依赖传统工具。</p></li><li><p>结合两者优势，可以开发出更高效的产品和服务。</p></li></ul><p>Q&amp;A 环节</p><ul><li><p>回答了关于数据分析、大模型调用工具的意义以及零基础学习建议等问题。</p></li><li><p>强调了提示词工程的重要性，并指出每项任务都需要具体工程设计。</p></li><li><p>解释了 MCP 与 OpenAI 规范的关系，明确 MCP 是对现有标准的补充而非替代。</p></li></ul><p>课件获取链接：<a href="https://pan.baidu.com/s/1vB3yTfDI3sKTiy_DrnS7Eg" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1vB3yTfDI3sKTiy_DrnS7Eg</a> 提取码: q42m</p>',17)])])}const u=i(p,[["render",n]]);export{h as __pageData,u as default};
